function blank() { return { customers:[], days:[], entries:[], columns:[], orders:[], teamOrders:[], items:[], teamItems:[], documents:[], teamDocuments:[], materials:[], messages:[], appointments:[], vacations:[] } }
function iso(value) { const d=value instanceof Date?value:new Date(String(value)+"T12:00:00"); return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0") }
function today() { return iso(new Date()) }
function day(value) { return new Date(String(value)+"T12:00:00") }
function shift(value, amount) { const d=day(value); d.setDate(d.getDate()+amount); return iso(d) }
function same(a,b) { return String(a)===String(b) }
function between(value,start,end) { return String(value)>=String(start)&&String(value)<=String(end) }
function workday(value) { const n=day(value).getDay(); return n>0&&n<6 }
function dailyTarget(value) { const n=day(value).getDay(); return n>0&&n<5?8:n===5?5:0 }
function number(value) { const n=Number(String(value??"").replace(",",".")); return Number.isFinite(n)?n:0 }
function escape(value) { return String(value??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&gt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]) }
function hours(value) { return number(value).toLocaleString("de-DE",{minimumFractionDigits:2,maximumFractionDigits:2})+"h" }
function euros(value) { return number(value).toLocaleString("de-DE",{style:"currency",currency:"EUR"}) }
function dateText(value) { return new Intl.DateTimeFormat("de-DE",{day:"2-digit",month:"long",year:"numeric"}).format(day(value)) }
function monthText(year,month) { return new Intl.DateTimeFormat("de-DE",{month:"long",year:"numeric"}).format(new Date(year,month,1)) }
function timeText(value) { return value?String(value).slice(0,5)+" Uhr":"–" }
function guid() { return crypto.randomUUID() }
function chief() { return state.profile?.role==="chief" }
function person() { return state.people.find(row=>row.id===state.activeId)||state.profile }
function personName(id) { return state.people.find(row=>row.id===id)?.username||"Unbekannt" }
function customerLabel(id,fallback) { return state.data.customers.find(row=>row.id===id)?.name||fallback||"" }
function permitted(view) { const permission=view==="time"?"planner":view;return chief()||!["time","customers","orders","calendar"].includes(view)||state.profile?.menu_permissions?.[permission]!==false }
function api(query) { return query.then(({data,error})=>{if(error)throw error;return data}) }
function notify(text, error=false) { state.toast={text,error}; render(); clearTimeout(notify.timer); notify.timer=setTimeout(()=>{state.toast=null;render()},4500) }
function asMinutes(value) { if(!/^\d\d:\d\d/.test(value||""))return null; const [h,m]=value.slice(0,5).split(":").map(Number);return h*60+m }
function plusMinutes(value,amount) { const start=asMinutes(value);if(start===null)return"";const total=((start+Math.round(amount))%1440+1440)%1440;return String(Math.floor(total/60)).padStart(2,"0")+":"+String(total%60).padStart(2,"0") }
function calculated(row) { const pause=Math.max(0,number(row.pause_hours)); const start=asMinutes(row.start_time), end=asMinutes(row.end_time); if(row.calculation_mode==="end_time"&&start!==null&&end!==null){const minutes=(end<start?end+1440:end)-start;return {...row,pause_hours:pause,executed_hours:Math.max(0,minutes/60-pause)}} const done=Math.max(0,number(row.executed_hours));return {...row,pause_hours:pause,executed_hours:done,end_time:row.start_time?plusMinutes(row.start_time,(done+pause)*60):""} }
function entriesFor(value=state.date) { return state.data.entries.filter(row=>same(row.work_date,value)).sort((a,b)=>String(a.created_at||a.id).localeCompare(String(b.created_at||b.id))) }
function dayStatus(value=state.date) { const vacation=state.data.vacations.find(row=>row.employee_id===state.activeId&&row.status==="approved"&&between(value,row.start_date,row.end_date)); const sick=state.data.days.find(row=>same(row.work_date,value)&&number(row.sick)>0); return {holiday:holidays[value]||"",vacation,sick,locked:Boolean(holidays[value]||vacation||sick)} }
function goal(value) { return dayStatus(value).locked?0:dailyTarget(value) }
function nextStart(value=state.date) { const last=entriesFor(value).at(-1);return last?calculated(last).end_time||"07:30":"07:30" }
function approvedVacationDays(id) { return state.data.vacations.filter(row=>row.employee_id===id&&row.status==="approved").reduce((sum,row)=>sum+number(row.requested_days),0) }
function vacationRemaining(id) { return Math.max(0,number(state.people.find(row=>row.id===id)?.vacation_allowance)-approvedVacationDays(id)) }
function countWorkdays(start,end) { let total=0;for(let value=start;value<=end;value=shift(value,1))if(workday(value)&&!holidays[value])total+=1;return total }
function overview() { const perDay=new Map();state.data.entries.forEach(row=>perDay.set(row.work_date,(perDay.get(row.work_date)||0)+calculated(row).executed_hours));const executed=[...perDay.values()].reduce((a,b)=>a+b,0);const overtime=[...perDay].reduce((sum,[value,done])=>sum+done-goal(value),0);return {executed,overtime,sick:state.data.days.filter(row=>number(row.sick)>0).length,vacation:approvedVacationDays(state.activeId),remaining:vacationRemaining(state.activeId)} }

async function loadPeople() { if(!chief()){state.people=[state.profile];return} const response=await db.functions.invoke("manage-employees",{body:{action:"list"}});if(response.error||response.data?.error)throw new Error(response.error?.message||response.data?.error);state.people=response.data.employees||[] }
async function reload() {
  const revision=++state.revision, id=state.activeId
  const loaded=await Promise.all([
    api(db.from("customers").select("*").order("name")),api(db.from("work_days").select("*").eq("employee_id",id)),api(db.from("time_entries").select("*").eq("employee_id",id).order("created_at")),api(db.from("custom_columns").select("*").eq("employee_id",id).order("position")),api(db.from("work_orders").select("*").eq("employee_id",id).order("work_date",{ascending:false})),api(db.from("materials").select("*").eq("active",true).order("name")),api(db.from("mailbox_messages").select("*").eq("recipient_id",state.profile.id).order("created_at",{ascending:false})),api(db.from("appointments").select("*").eq("employee_id",id).order("event_date")),api((chief()?db.from("vacation_requests").select("*"):db.from("vacation_requests").select("*").eq("employee_id",id)).order("start_date")),chief()?api(db.from("work_orders").select("*").order("work_date",{ascending:false})):Promise.resolve([]),
  ])
  const ids=loaded[4].map(row=>row.id),teamIds=loaded[9].map(row=>row.id),[items,documents,teamItems,teamDocuments]=await Promise.all([ids.length?api(db.from("work_order_items").select("*").in("work_order_id",ids).order("created_at")):Promise.resolve([]),ids.length?api(db.from("work_order_documents").select("*").in("work_order_id",ids).order("created_at")):Promise.resolve([]),teamIds.length?api(db.from("work_order_items").select("*").in("work_order_id",teamIds).order("created_at")):Promise.resolve([]),teamIds.length?api(db.from("work_order_documents").select("*").in("work_order_id",teamIds).order("created_at")):Promise.resolve([])])
  if(revision!==state.revision)return
  state.data={customers:loaded[0],days:loaded[1],entries:loaded[2],columns:loaded[3],orders:loaded[4],materials:loaded[5],messages:loaded[6],appointments:loaded[7],vacations:loaded[8],teamOrders:loaded[9],items,teamItems,documents,teamDocuments};render()
}
function queueReload(){clearTimeout(state.timer);state.timer=setTimeout(()=>reload().catch(()=>{}),250)}
function subscribe(){if(state.channel)db.removeChannel(state.channel);state.channel=db.channel("worktime-new-"+state.session.user.id).on("postgres_changes",{event:"*",schema:"public",table:"customers"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"materials"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"time_entries"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"work_orders"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"work_order_documents"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"work_days"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"vacation_requests"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"mailbox_messages"},queueReload).on("postgres_changes",{event:"*",schema:"public",table:"appointments"},queueReload).subscribe()}
async function boot(){state.loading=true;render();state.session=(await db.auth.getSession()).data.session;if(!state.session){state.loading=false;render();return}try{state.profile=await api(db.from("profiles").select("*").eq("id",state.session.user.id).single());await loadPeople();state.activeId=state.activeId||state.profile.id;await reload();subscribe()}catch(error){await db.auth.signOut();state.session=null;state.profile=null;notify(error.message||"Anmeldung fehlgeschlagen.",true)}state.loading=false;render()}

async function mutate(apply, save, text="") { ++state.revision;const undo=apply();render();try{const result=await save();if(text)notify(text);reload().catch(()=>{});return result}catch(error){undo?.();render();throw error} }
function add(list,row){list.push(row);return()=>{const at=list.indexOf(row);if(at>=0)list.splice(at,1)}}
function remove(list,id){const at=list.findIndex(row=>row.id===id),row=list[at];if(at>=0)list.splice(at,1);return()=>{if(at>=0)list.splice(at,0,row)}}
