async function requestVacation(form){const start=form.startDate.value,end=form.endDate.value,requested=countWorkdays(start,end);if(end<start||!requested)throw new Error("Bitte mindestens einen Arbeitstag auswählen.");if(requested>vacationRemaining(state.profile.id))throw new Error("Resturlaub reicht nicht aus.");const row={id:guid(),employee_id:state.profile.id,start_date:start,end_date:end,requested_days:requested,status:chief()?"approved":"requested",decision_note:form.note.value.trim()};state.form="";await mutate(()=>add(state.data.vacations,row),()=>api(db.from("vacation_requests").insert(row).select().single()).then(saved=>Object.assign(row,saved)),chief()?"Urlaub automatisch genehmigt.":"Urlaubsantrag gesendet.")}
