function toast(){return state.toast?"<div class='toast "+(state.toast.error?"error":"")+"'>"+escape(state.toast.text)+"</div>":""}
function login(){return "<main class='login'><section><div class='mark'>AZ</div><p class='eyebrow'>GEMEINSAME ZEITERFASSUNG</p><h1>Willkommen zurück</h1><p>Arbeitszeit, Kunden, Arbeitsscheine und Teamplanung.</p><form data-form='login'><label>Benutzername<input name='username' autocomplete='username' required></label><label>Passwort<input name='password' type='password' autocomplete='current-password' required></label><button class='primary'>Anmelden</button></form><button class='link' data-action='forgot'>Passwort vergessen?</button>"+toast()+"</section></main>"}
function shell(){const nav=[["time","Zeiterfassung"],["customers","Kunden"],["orders","Arbeitsscheine"],["calendar","Kalender"],["mailbox","Postfach"],["settings","Einstellungen"]].concat(chief()?[["assignments","Aufträge Mitarbeiter"]]:[]).filter(([view])=>permitted(view)),unread=state.data.messages.filter(row=>!row.read_at&&!row.deleted_at).length;return "<header><div class='brand'><span>AZ</span><strong>Arbeitszeit</strong></div>"+(chief()?"<label class='person'>Daten von<select id='person-select'>"+state.people.map(row=>"<option value='"+row.id+"'"+(row.id===state.activeId?" selected":"")+">"+escape(row.username)+(row.role==="chief"?" (Chef)":"")+"</option>").join("")+"</select></label>":"")+"<button class='link' data-action='logout'>Abmelden</button></header><nav>"+nav.map(([view,title])=>"<button data-view='"+view+"' class='"+((state.view===view||(view==="customers"&&state.view==="customer-orders"))?"selected":"")+"'>"+title+(view==="mailbox"&&unread?" ("+unread+")":"")+"</button>").join("")+"</nav>"+renderView()+toast()}
function weekDates(value=state.date){const start=day(value),offset=(start.getDay()+6)%7;start.setDate(start.getDate()-offset);return Array.from({length:7},(_,index)=>iso(new Date(start.getFullYear(),start.getMonth(),start.getDate()+index)))}
function dateBar(){const labels=["Mo","Di","Mi","Do","Fr","Sa","So"],days=weekDates(),selected=day(state.date);return "<section class='datebar'><button data-action='date-prev' aria-label='Voriger Tag'>‹</button><input id='date-select' type='date' value='"+state.date+"'><button data-action='date-next' aria-label='Nächster Tag'>›</button><strong>"+dateText(state.date)+"</strong></section><section class='weekcard'><div class='weekcard-head'><span>Aktive Woche</span><b>"+monthText(selected.getFullYear(),selected.getMonth())+"</b></div><section class='weekpicker' aria-label='Wochenauswahl'>"+days.map((value,index)=>{const st=dayStatus(value),marker=st.sick?"sick":st.vacation?"vacation":st.holiday?"holiday":"";return "<button data-action='week-day' data-date='"+value+"' class='"+(same(value,state.date)?"selected ":"")+(index>4?"weekend ":"")+marker+"'><span>"+labels[index]+"</span><b>"+day(value).getDate()+"</b>"+(marker?"<i aria-hidden='true'></i>":"")+"</button>"}).join("")+"</section></section>"}

function timeView(){const st=dayStatus(),rows=entriesFor(),done=rows.reduce((sum,row)=>sum+calculated(row).executed_hours,0),overtime=done-goal(state.date),absence=st.holiday?"<div class='absence holiday'>"+escape(st.holiday)+" · Feiertag in NRW</div>":st.sick?"<div class='absence sick'>Krank gemeldet</div>":st.vacation?"<div class='absence vacation'>Urlaub genehmigt</div>":"",sickButton=chief()?"<button data-action='sick'>"+(st.sick?"Krankheit entfernen":"Krankheit hinzufügen")+"</button>":(!st.sick?"<button data-action='sick'>Als krank markieren</button>":"<span class='tag sick'>Krank gemeldet</span>");return "<main><section class='hero'><p class='eyebrow'>ZEITERFASSUNG</p><h1>Arbeitszeit und Kunden</h1><p>Stunden oder Endzeit eingeben – die fehlende Angabe wird automatisch berechnet.</p></section>"+dateBar()+"<section class='metrics'><div><span>Sollzeit</span><strong>"+hours(goal(state.date))+"</strong></div><div><span>Ausgeführt</span><strong>"+hours(done)+"</strong></div><div><span>Überstunden</span><strong class='"+(overtime>0?"plus":overtime<0?"minus":"")+"'>"+(Math.abs(overtime)<.005?"–":hours(overtime))+"</strong></div></section>"+absence+"<section class='toolbar'><div><h2>Kunden & Zeiten</h2><p>Der erste Kunde beginnt standardmäßig um 07:30 Uhr.</p></div><div>"+sickButton+"<button class='primary' data-action='entry-add'"+(st.locked||!workday(state.date)?" disabled":"")+">+ Kunde</button></div></section><datalist id='customer-list'>"+state.data.customers.map(row=>"<option value='"+escape(row.name)+"'>").join("")+"</datalist><section class='cards'>"+(rows.length?rows.map(entryCard).join(""):"<p class='empty'>Noch kein Kunde erfasst.</p>")+"</section></main>"}
function entryCard(row,index){const value=calculated(row),extras=state.data.columns.map(column=>"<label>"+escape(column.name)+"<input data-entry='"+column.id+"' data-id='"+row.id+"' value='"+escape(row.custom_fields?.[column.id]||"")+"'></label>").join("");return "<article class='card entry'><div class='cardhead'><b>"+(index+1)+"</b><label class='wide'>Kunde<input list='customer-list' data-entry='customer' data-id='"+row.id+"' value='"+escape(customerLabel(row.customer_id,row.customer_name))+"' placeholder='Kundenname'></label><button class='danger icon' data-action='entry-delete' data-id='"+row.id+"'>×</button></div><div class='fields'><label>Beginn<input type='time' data-entry='start_time' data-id='"+row.id+"' value='"+escape(value.start_time||"")+"'></label><label>Ende<input type='time' data-entry='end' data-id='"+row.id+"' value='"+escape(value.end_time||"")+"'></label><label>Pause (Std.)<input inputmode='decimal' data-entry='pause_hours' data-id='"+row.id+"' value='"+escape(value.pause_hours)+"'></label><label>Ausgeführt<input inputmode='decimal' data-entry='hours' data-id='"+row.id+"' value='"+escape(value.executed_hours)+"'></label></div>"+(extras?"<div class='fields extra'>"+extras+"</div>":"")+"</article>"}
function customersView(){return "<main><section class='hero'><p class='eyebrow'>KUNDEN</p><h1>Kunden verwalten</h1><p>Kundendaten werden auf allen angemeldeten Geräten synchronisiert.</p></section><form data-form='customer' class='addline'><label>Kundenname<input name='name' required placeholder='Neuen Kunden eingeben'></label><button class='primary'>Kunde anlegen</button></form><section class='cards'>"+(state.data.customers.length?state.data.customers.map(customerCard).join(""):"<p class='empty'>Noch keine Kunden vorhanden.</p>")+"</section></main>"}
function customerCard(row){const data=row.custom_fields||{},done=state.data.entries.filter(entry=>entry.customer_id===row.id||entry.customer_name===row.name).reduce((sum,entry)=>sum+calculated(entry).executed_hours,0),remove=chief()?"<button class='danger' data-action='customer-delete' data-id='"+row.id+"'>Löschen</button>":"",title=chief()?"<h2><button class='customer-link' data-action='customer-orders' data-id='"+row.id+"'>"+escape(row.name)+"</button></h2>":"<h2>"+escape(row.name)+"</h2>";return "<article class='card'><div class='cardhead'><div>"+title+"<p>"+hours(done)+" ausgeführt"+(chief()?" · Arbeitsscheine öffnen":"")+"</p></div>"+remove+"</div><form data-form='customer-details' data-id='"+row.id+"' class='formgrid'><label>Kundenname<input name='name' value='"+escape(row.name)+"' required></label><label>Adresse<input name='address' value='"+escape(data.address)+"'></label><label>Ort<input name='city' value='"+escape(data.city)+"'></label><label>Postleitzahl<input name='postal_code' inputmode='numeric' value='"+escape(data.postal_code)+"'></label><label>E-Mail Adresse<input name='email' type='email' value='"+escape(data.email)+"'></label><label>Tel. privat<input name='phone_private' type='tel' value='"+escape(data.phone_private)+"'></label><label>Tel. Mobil<input name='phone_mobile' type='tel' value='"+escape(data.phone_mobile)+"'></label><button>Kontaktdaten speichern</button></form></article>"}
function customerOrderLine(order){const items=state.data.teamItems.filter(item=>item.work_order_id===order.id),documents=state.data.teamDocuments.filter(document=>document.work_order_id===order.id),materialTotal=items.reduce((sum,item)=>sum+number(item.quantity)*number(item.unit_price),0),work=calculated(order),invoice="<label class='invoice-toggle'><input type='checkbox' data-invoice='"+order.id+"'"+(order.invoiced?" checked":"")+"> <span>Abgerechnet</span></label>",materials=items.length?items.map(item=>"<li>"+escape(item.position_name)+" · "+item.quantity+" × "+euros(item.unit_price)+"</li>").join(""):"<li>Keine Materialien</li>",files=documents.length?"<p class='customer-documents'>Dokumente: "+documents.map(document=>escape(document.file_name)).join(", ")+"</p>":"";return "<article class='customer-order-line "+(order.invoiced?"is-invoiced":"is-open")+"'><div class='cardhead'><div><small>"+dateText(order.work_date)+" · "+escape(personName(order.employee_id))+"</small><h3>"+escape(order.title||"Arbeitsschein")+"</h3></div>"+invoice+"</div><p class='facts'>"+timeText(order.start_time)+" – "+timeText(work.end_time)+" · "+hours(work.executed_hours)+"</p>"+(order.notes?"<p>"+escape(order.notes)+"</p>":"")+(order.documentation?"<p class='customer-documentation'><b>Dokumentation:</b> "+escape(order.documentation)+"</p>":"")+"<div class='invoice-materials'><b>Material · "+euros(materialTotal)+"</b><ul>"+materials+"</ul></div>"+files+"</article>"}
function customerOrdersView(){if(!chief())return customersView();const customer=state.data.customers.find(row=>row.id===state.selectedCustomerId);if(!customer)return customersView();const orders=state.data.teamOrders.filter(order=>order.customer_id===customer.id||(!order.customer_id&&order.customer_name===customer.name)).sort((a,b)=>String(b.work_date).localeCompare(String(a.work_date))||String(b.created_at||"").localeCompare(String(a.created_at||""))),open=orders.filter(order=>!order.invoiced),invoiced=orders.filter(order=>order.invoiced),openHours=open.reduce((sum,order)=>sum+calculated(order).executed_hours,0),openMaterial=open.flatMap(order=>state.data.teamItems.filter(item=>item.work_order_id===order.id)).reduce((sum,item)=>sum+number(item.quantity)*number(item.unit_price),0),openSheet=open.length?"<section class='invoice-bundle'><div class='invoice-bundle-head'><div><p class='eyebrow'>SAMMELARBEITSSCHEIN</p><h2>Alle offenen Arbeitsscheine</h2><p>"+open.length+" Arbeitsschein"+(open.length===1?"":"e")+" · "+hours(openHours)+" · Material "+euros(openMaterial)+"</p></div><span class='invoice-status open'>Noch nicht abgerechnet</span></div>"+open.map(customerOrderLine).join("")+"</section>":"<p class='empty'>Es gibt keine offenen Arbeitsscheine.</p>";return "<main><section class='hero'><p class='eyebrow'>KUNDE · ARBEITSSCHEINE</p><h1>"+escape(customer.name)+"</h1><p>Offene Arbeitsscheine sind zu einem Sammelarbeitsschein zusammengefasst.</p></section><p><button data-action='customer-orders-back'>← Zurück zu Kunden</button></p><section class='invoice-section'><h2>Offen</h2>"+openSheet+"</section><section class='invoice-section'><h2>Bereits abgerechnet</h2>"+(invoiced.length?"<div class='cards'>"+invoiced.map(customerOrderLine).join("")+"</div>":"<p class='empty'>Noch keine abgerechneten Arbeitsscheine.</p>")+"</section></main>"}
function ordersView(){return "<main><section class='hero'><p class='eyebrow'>ARBEITSSCHEINE</p><h1>Material, Kosten und Zeiten</h1><p>Ein Arbeitsschein ergänzt die Zeiterfassung automatisch.</p></section><form data-form='order' class='formgrid'><label>Datum<input name='workDate' type='date' value='"+state.date+"' required></label><label>Kunde<input name='customerName' list='customer-list' required></label><label>Titel<input name='title' placeholder='z. B. Reparatur'></label><label>Arbeitsbeginn<input name='startTime' type='time' value='"+nextStart()+"'></label><label>Arbeitsende (oder Stunden)<input name='endTime' type='time'></label><label>Pause (Stunden)<input name='pauseHours' inputmode='decimal' value='0'></label><label>Ausgeführte Stunden (oder Ende)<input name='executedHours' inputmode='decimal'></label><label class='full'>Notiz<textarea name='notes'></textarea></label><label class='full'>Dokumentation<textarea name='documentation' placeholder='Ausgeführte Arbeiten, Besonderheiten oder Hinweise dokumentieren'></textarea></label><button class='primary'>Arbeitsschein anlegen</button></form><datalist id='customer-list'>"+state.data.customers.map(row=>"<option value='"+escape(row.name)+"'>").join("")+"</datalist><section class='cards'>"+(state.data.orders.length?state.data.orders.map(orderCard).join(""):"<p class='empty'>Noch keine Arbeitsscheine vorhanden.</p>")+"</section></main>"}
function orderCard(order){const items=state.data.items.filter(row=>row.work_order_id===order.id),documents=state.data.documents.filter(row=>row.work_order_id===order.id),total=items.reduce((sum,row)=>sum+number(row.quantity)*number(row.unit_price),0);return "<article class='card'><div class='cardhead'><div><small>"+dateText(order.work_date)+"</small><h2>"+escape(order.customer_name)+"</h2><p>"+escape(order.title||"Arbeitsschein")+"</p></div><button class='danger' data-action='order-delete' data-id='"+order.id+"'>Löschen</button></div><p class='facts'>"+timeText(order.start_time)+" – "+timeText(calculated(order).end_time)+" · "+hours(calculated(order).executed_hours)+"</p>"+(order.notes?"<p>"+escape(order.notes)+"</p>":"")+(order.documentation?"<div class='items'><h3>Dokumentation</h3><p>"+escape(order.documentation)+"</p></div>":"")+"<div class='items'>"+(items.length?items.map(item=>"<p>"+escape(item.position_name)+" · "+item.quantity+" × "+euros(item.unit_price)+" = "+euros(number(item.quantity)*number(item.unit_price))+" <button class='link' data-action='item-delete' data-id='"+item.id+"'>Entfernen</button></p>").join(""):"<p>Keine Materialien.</p>")+"</div><form data-form='item' data-order-id='"+order.id+"' class='addline'><label>Artikel<input name='materialName' required placeholder='Artikel eingeben'></label><label>Menge<input name='quantity' value='1'></label><button>+ Material</button></form><p class='material-hint'>Artikel werden beim Hinzufügen mit der Materialliste abgeglichen.</p><p class='total'>Materialsumme <b>"+euros(total)+"</b></p><div class='items'><h3>Dokumente</h3>"+(documents.length?documents.map(row=>"<p>"+escape(row.file_name)+" <button class='link' data-action='document-open' data-id='"+row.id+"'>Öffnen</button> <button class='link' data-action='document-delete' data-id='"+row.id+"'>Entfernen</button></p>").join(""):"<p>Noch keine Dokumente hochgeladen.</p>")+"</div><form data-form='document' data-order-id='"+order.id+"' class='addline'><label>Dokument Upload<input name='documents' type='file' multiple></label><button>Dokumente hochladen</button></form></article>"}

function calendarView(){const first=new Date(state.year,state.month,1),offset=(first.getDay()+6)%7,cells=[];for(let i=0;i<42;i++){const d=new Date(state.year,state.month,1-offset+i),value=iso(d),vacation=state.data.vacations.find(row=>row.employee_id===state.activeId&&row.status!=="rejected"&&between(value,row.start_date,row.end_date)),sick=state.data.days.some(row=>same(row.work_date,value)&&number(row.sick)>0),appointment=state.data.appointments.some(row=>same(row.event_date,value)),work=state.data.entries.some(row=>same(row.work_date,value));const classes=[d.getMonth()===state.month?"":"outside",same(value,state.date)?"selected":"",vacation?.status==="approved"?"approved":"",vacation?.status==="requested"?"requested":"",sick?"sick":""].filter(Boolean).join(" ");cells.push("<button class='day "+classes+"' data-action='calendar-day' data-date='"+value+"'><b>"+d.getDate()+"</b><span>"+(work?"●":"")+(appointment?"◆":"")+(vacation?"■":"")+(sick?"✚":"")+"</span></button>")}const st=dayStatus(),appointments=state.data.appointments.filter(row=>same(row.event_date,state.date));return "<main><section class='hero'><p class='eyebrow'>KALENDER</p><h1>Kalender von "+escape(person().username)+"</h1><p>Gelb: Urlaub beantragt · Grün: genehmigt · Rot: Krankheit.</p></section><div class='actions'><button class='primary' data-action='form-vacation'>Urlaub beantragen</button><button data-action='form-appointment'>Kundentermin vormerken</button>"+(chief()?"<button data-action='sick'>"+(st.sick?"Krankheit entfernen":"Krankheit hinzufügen")+"</button>":(!st.sick?"<button data-action='sick'>Als krank markieren</button>":""))+"</div>"+calendarForm()+"<section class='calendar'><div class='monthnav'><button data-action='month-prev'>‹</button><h2>"+monthText(state.year,state.month)+"</h2><button data-action='month-next'>›</button></div><div class='weekdays'><span>Mo</span><span>Di</span><span>Mi</span><span>Do</span><span>Fr</span><span>Sa</span><span>So</span></div><div class='grid'>"+cells.join("")+"</div><p class='legend'>● Arbeitszeit · ◆ Termin · ■ Urlaub · ✚ Krankheit</p></section><section class='card'><h2>"+dateText(state.date)+"</h2><p>"+(st.holiday?escape(st.holiday)+" · ":"")+(st.sick?"Krank gemeldet · ":"")+(st.vacation?"Urlaub genehmigt":"Keine Abwesenheit")+"</p>"+appointments.map(row=>"<p>Termin: <b>"+escape(row.title)+"</b> <button class='link' data-action='appointment-delete' data-id='"+row.id+"'>Entfernen</button></p>").join("")+"</section></main>"}
function calendarForm(){if(state.form==="vacation")return "<form data-form='vacation' class='formgrid panel'><h2>Urlaub beantragen</h2><label>Von<input name='startDate' type='date' value='"+state.date+"'></label><label>Bis<input name='endDate' type='date' value='"+state.date+"'></label><label class='full'>Hinweis<input name='note'></label><button class='primary'>Antrag senden</button><button type='button' data-action='form-close'>Abbrechen</button></form>";if(state.form==="appointment")return "<form data-form='appointment' class='formgrid panel'><h2>Kundentermin vormerken</h2><label>Datum<input name='eventDate' type='date' value='"+state.date+"'></label><label>Kunde<input name='customerName' list='customer-list'></label><label>Titel<input name='title' required></label><label class='full'>Notiz<input name='notes'></label><button class='primary'>Termin speichern</button><button type='button' data-action='form-close'>Abbrechen</button></form>";const vacation=state.data.vacations.find(row=>row.employee_id===state.activeId&&row.status!=="rejected"&&between(state.date,row.start_date,row.end_date));return vacation&&chief()?"<section class='card'><p>Urlaub dieses Tages verwalten.</p><button class='danger' data-action='vacation-decision' data-id='"+vacation.id+"' data-value='rejected'>Urlaub entfernen</button></section>":""}
function mailboxView(){const messages=state.data.messages.filter(row=>state.folder==="trash"?Boolean(row.deleted_at):!row.deleted_at&&(state.folder==="all"||state.folder==="read"?Boolean(row.read_at):!row.read_at));return "<main><section class='hero'><p class='eyebrow'>POSTFACH</p><h1>Mein internes Postfach</h1><p>Beim Öffnen werden Nachrichten automatisch als gelesen markiert.</p></section><div class='tabs'>"+[["all","Alle"],["unread","Ungelesen"],["read","Gelesen"],["trash","Papierkorb"]].map(([value,title])=>"<button data-action='mail-folder' data-folder='"+value+"' class='"+(state.folder===value?"selected":"")+"'>"+title+"</button>").join("")+"</div><section class='cards'>"+(messages.length?messages.map(mailCard).join(""):"<p class='empty'>Keine Nachrichten in diesem Ordner.</p>")+"</section></main>"}
function mailCard(row){const request=row.body?.request_id?state.data.vacations.find(item=>item.id===row.body.request_id):null,controls=chief()&&request?.status==="requested"?"<p><button class='primary' data-action='vacation-decision' data-id='"+request.id+"' data-value='approved'>Genehmigen</button> <button class='danger' data-action='vacation-decision' data-id='"+request.id+"' data-value='rejected'>Ablehnen</button></p>":"",trash=row.deleted_at?"<button class='link' data-action='mail-restore' data-id='"+row.id+"'>Wiederherstellen</button>":"<button class='link' data-action='mail-delete' data-id='"+row.id+"'>Löschen</button>";return "<article class='card mail "+(!row.read_at?"unread":"")+"' data-action='mail-open' data-id='"+row.id+"'><small>"+escape(row.message_type)+" · "+new Intl.DateTimeFormat("de-DE",{dateStyle:"short",timeStyle:"short"}).format(new Date(row.created_at))+"</small><h2>"+escape(row.title)+"</h2><p>"+escape(row.body?.message||row.body?.username||"Nachricht öffnen für Details.")+"</p>"+(request?"<p>Urlaub: "+dateText(request.start_date)+" bis "+dateText(request.end_date)+" · Status: "+escape(request.status)+"</p>":"")+controls+"<p>"+trash+"</p></article>"}
function renderView(){return state.view==="time"?timeView():state.view==="customers"?customersView():state.view==="customer-orders"?customerOrdersView():state.view==="orders"?ordersView():state.view==="calendar"?calendarView():state.view==="mailbox"?mailboxView():state.view==="assignments"?assignmentsView():state.view==="assignment-detail"?assignmentDetailView():settingsView()}
function render(){if(state.loading){root.innerHTML="<main class='loading'>Arbeitszeit wird vorbereitet …</main>";return}root.innerHTML=state.session?shell():login();if(state.session&&!chief()){const password=root.querySelector("form[data-form='account'] input[name='password']")?.closest("label");if(password)password.hidden=true}const workDate=root.querySelector("form[data-form='order'] input[name='workDate']"),submit=root.querySelector("form[data-form='order'] button.primary");if(workDate&&submit&&dayStatus(workDate.value).sick){submit.disabled=true;submit.title="An Krankheitstagen sind keine Arbeitsscheine möglich."}}

function employeeCard(row){if(row.id===state.profile.id)return "<p><b>"+escape(row.username)+"</b> · Chef</p>";const p=row.menu_permissions||{};return "<form data-form='employee-update-full' data-id='"+row.id+"' class='employee'><h3>"+escape(row.username)+"</h3><label>Benutzername<input name='username' value='"+escape(row.username)+"'></label><label>Neues Passwort<input name='password' type='password' placeholder='Unverändert'></label><label>Urlaubstage<input name='allowance' value='"+escape(row.vacation_allowance)+"'></label><label><input type='checkbox' name='time'"+(p.planner!==false?" checked":"")+"> Zeiterfassung</label><label><input type='checkbox' name='customers'"+(p.customers!==false?" checked":"")+"> Kunden</label><label><input type='checkbox' name='orders'"+(p.orders!==false?" checked":"")+"> Arbeitsscheine</label><label><input type='checkbox' name='calendar'"+(p.calendar!==false?" checked":"")+"> Kalender</label><button>Speichern</button><button type='button' class='danger' data-action='employee-delete' data-id='"+row.id+"'>Löschen</button></form>"}
function settingsView(){const current=person(),summary=overview(),account="<section class='card'><h2>Mein Benutzerkonto</h2><form data-form='account' class='formgrid'><label>Benutzername<input name='username' value='"+escape(state.profile.username)+"'></label><label>Neues Passwort<input name='password' type='password' placeholder='Leer lassen = unverändert'></label>"+(chief()?"<label>Mein Urlaubsanspruch<input name='vacationAllowance' value='"+escape(state.profile.vacation_allowance)+"'></label>":"")+"<button class='primary'>Konto speichern</button></form></section>",chiefTools=chief()?"<section class='card'><h2>Zusätzliche Eingabefelder Zeiterfassung</h2><form data-form='column' class='addline'><label>Feldbezeichnung<input name='name' required placeholder='z. B. Fahrzeug'></label><button class='primary'>Feld hinzufügen</button></form>"+(state.data.columns.length?state.data.columns.map(row=>"<p>"+escape(row.name)+" <button class='link' data-action='column-delete' data-id='"+row.id+"'>Entfernen</button></p>").join(""):"<p>Keine zusätzlichen Eingabefelder.</p>")+"</section><section class='card'><h2>Materialkatalog</h2><form data-form='material' class='addline'><label>Material<input name='name' required></label><label>Preis pro Stück (€)<input name='price' required></label><button class='primary'>Material anlegen</button></form>"+state.data.materials.map(row=>"<p>"+escape(row.name)+" · "+euros(row.unit_price)+" <button class='link' data-action='material-edit' data-id='"+row.id+"'>Preis ändern</button> <button class='link' data-action='material-delete' data-id='"+row.id+"'>Entfernen</button></p>").join("")+"</section><section class='card'><h2>Mitarbeiter verwalten</h2><form data-form='employee' class='formgrid'><label>Benutzername<input name='username' required></label><label>Passwort<input name='password' type='password' required></label><button class='primary'>Mitarbeiter hinzufügen</button></form><div class='people'>"+state.people.map(employeeCard).join("")+"</div></section>":"";return "<main><section class='hero'><p class='eyebrow'>EINSTELLUNGEN</p><h1>"+escape(current.username)+"</h1><p>Statistik, Konto, Team und Berechtigungen.</p></section><section class='metrics'><div><span>Stunden</span><strong>"+hours(summary.executed)+"</strong></div><div><span>Überstunden</span><strong>"+hours(summary.overtime)+"</strong></div><div><span>Krankheit</span><strong>"+summary.sick+" Tage</strong></div><div><span>Resturlaub</span><strong>"+summary.remaining+" Tage</strong></div></section><button class='primary' data-action='pdf'>Daten als PDF herunterladen</button>"+account+chiefTools+"</main>"}

root.addEventListener("submit",async event=>{const form=event.target.closest("form");if(!form)return;event.preventDefault();try{if(form.dataset.form==="login"){const result=await db.auth.signInWithPassword({email:form.username.value.trim().toLowerCase()+"@arbeitszeit.local",password:form.password.value});if(result.error)throw new Error("Benutzername oder Passwort ist nicht korrekt.")}else if(form.dataset.form==="customer"){await ensureCustomer(form.name.value);notify("Kunde angelegt.")}else if(form.dataset.form==="customer-field"){const row=state.data.customers.find(item=>item.id===form.dataset.id),key=form.key.value.trim(),value=form.value.value.trim();if(!row||!key||!value)throw new Error("Bitte Feld und Wert eingeben.");const before={...(row.custom_fields||{})},fields={...before,[key]:value};await mutate(()=>{row.custom_fields=fields;return()=>row.custom_fields=before},()=>api(db.from("customers").update({custom_fields:fields}).eq("id",row.id).select().single()).then(saved=>Object.assign(row,saved)),"Kundendaten gespeichert.")}else if(form.dataset.form==="order")await createOrder(form);else if(form.dataset.form==="item")await addItem(form);else if(form.dataset.form==="vacation")await requestVacation(form);else if(form.dataset.form==="appointment")await createAppointment(form);else if(form.dataset.form==="material"){if(!chief())throw new Error("Nur der Chef verwaltet Materialien.");const row={id:guid(),name:form.name.value.trim(),unit_price:Math.max(0,number(form.price.value)),active:true};if(!row.name)throw new Error("Bitte Material eingeben.");await mutate(()=>add(state.data.materials,row),()=>api(db.from("materials").insert(row).select().single()).then(saved=>Object.assign(row,saved)),"Material angelegt.")}else if(form.dataset.form==="account"){const response=await db.functions.invoke("manage-employees",{body:{action:"self-update",username:form.username.value,password:form.password.value,vacationAllowance:form.vacationAllowance?.value}});if(response.error||response.data?.error)throw new Error(response.error?.message||response.data?.error);await boot();notify("Benutzerkonto gespeichert.")}else if(form.dataset.form==="employee"){const response=await db.functions.invoke("manage-employees",{body:{action:"create",username:form.username.value,password:form.password.value}});if(response.error||response.data?.error)throw new Error(response.error?.message||response.data?.error);await loadPeople();render();notify("Mitarbeiter angelegt.")}else if(form.dataset.form==="employee-update"){const response=await db.functions.invoke("manage-employees",{body:{action:"update",employeeId:form.dataset.id,vacationAllowance:form.allowance.value,menuPermissions:{planner:form.time.checked,customers:form.customers.checked,orders:form.orders.checked,calendar:form.calendar.checked}}});if(response.error||response.data?.error)throw new Error(response.error?.message||response.data?.error);await loadPeople();render();notify("Mitarbeiter gespeichert.")}}catch(error){notify(error.message||"Aktion fehlgeschlagen.",true)}})
root.addEventListener("change",async event=>{const el=event.target;try{if(el.id==="person-select"){state.activeId=el.value;state.form="";await reload()}else if(el.id==="date-select"){state.date=el.value;state.month=day(state.date).getMonth();state.year=day(state.date).getFullYear();render()}else if(el.dataset.invoice)await setOrderInvoiced(el.dataset.invoice,el.checked);else if(el.dataset.entry)await saveEntry(el.dataset.id,el.dataset.entry,el.value)}catch(error){notify(error.message||"Änderung konnte nicht gespeichert werden.",true)}})
root.addEventListener("click",async event=>{const button=event.target.closest("button");if(!button)return;try{if(button.dataset.view){if(!permitted(button.dataset.view))throw new Error("Dieses Menü ist nicht freigegeben.");state.view=button.dataset.view;state.form="";render();return}const action=button.dataset.action;if(action==="logout"){if(state.channel)await db.removeChannel(state.channel);await db.auth.signOut();state.session=null;state.profile=null;state.people=[];state.activeId=null;state.selectedCustomerId=null;state.data=blank();render()}else if(action==="forgot"){const username=window.prompt("Benutzername eingeben. Der Chef wird vertraulich informiert.");if(username!==null){const response=await db.functions.invoke("request-password-help",{body:{username}});if(response.error)throw response.error;notify("Wenn ein Konto gefunden wurde, ist der Chef informiert.")}}else if(action==="date-prev"){state.date=shift(state.date,-1);render()}else if(action==="date-next"){state.date=shift(state.date,1);render()}else if(action==="customer-orders"){if(!chief())throw new Error("Nur der Chef kann Kundenarbeitsscheine ansehen.");state.selectedCustomerId=button.dataset.id;state.view="customer-orders";render()}else if(action==="customer-orders-back"){state.selectedCustomerId=null;state.view="customers";render()}else if(action==="entry-add")await addEntry();else if(action==="entry-delete"&&window.confirm("Zeiterfassungszeile wirklich löschen?"))await deleteEntry(button.dataset.id);else if(action==="sick"){await setSick(dayStatus().sick?0:1)}else if(action==="order-delete"&&window.confirm("Arbeitsschein und Zeiterfassung wirklich löschen?"))await deleteOrder(button.dataset.id);else if(action==="item-delete")await mutate(()=>remove(state.data.items,button.dataset.id),()=>api(db.from("work_order_items").delete().eq("id",button.dataset.id).select("id")),"Materialposition entfernt.");else if(action==="customer-delete"&&window.confirm("Kunde löschen? Bereits erfasste Arbeitszeiten bleiben erhalten."))await mutate(()=>remove(state.data.customers,button.dataset.id),()=>api(db.from("customers").delete().eq("id",button.dataset.id).select("id")),"Kunde gelöscht.");else if(action==="customer-field-delete"){const row=state.data.customers.find(item=>item.id===button.dataset.id),before={...(row?.custom_fields||{})},fields={...before};delete fields[button.dataset.key];await mutate(()=>{row.custom_fields=fields;return()=>row.custom_fields=before},()=>api(db.from("customers").update({custom_fields:fields}).eq("id",row.id).select().single()).then(saved=>Object.assign(row,saved)),"Kundendatenfeld entfernt.")}else if(action==="form-vacation"||action==="form-appointment"){state.form=action==="form-vacation"?"vacation":"appointment";render()}else if(action==="form-close"){state.form="";render()}else if(action==="month-prev"||action==="month-next"){const d=new Date(state.year,state.month+(action==="month-next"?1:-1),1);state.year=d.getFullYear();state.month=d.getMonth();render()}else if(action==="calendar-day"){state.date=button.dataset.date;render()}else if(action==="appointment-delete")await mutate(()=>remove(state.data.appointments,button.dataset.id),()=>api(db.from("appointments").delete().eq("id",button.dataset.id).select("id")),"Termin entfernt.");else if(action==="mail-folder"){state.folder=button.dataset.folder;render()}else if(action==="mail-open"){const row=state.data.messages.find(item=>item.id===button.dataset.id);if(row&&!row.read_at){const before=row.read_at;row.read_at=new Date().toISOString();await mutate(()=>()=>row.read_at=before,()=>api(db.from("mailbox_messages").update({read_at:row.read_at}).eq("id",row.id).select().single()).then(saved=>Object.assign(row,saved)))}}else if(action==="vacation-decision")await decideVacation(button.dataset.id,button.dataset.value);else if(action==="pdf")await createPdf();else if(action==="material-delete"&&window.confirm("Material entfernen?"))await mutate(()=>remove(state.data.materials,button.dataset.id),()=>api(db.from("materials").update({active:false}).eq("id",button.dataset.id).select().single()),"Material entfernt.");else if(action==="employee-delete"&&window.confirm("Mitarbeiter mit seinen Daten löschen?")){const response=await db.functions.invoke("manage-employees",{body:{action:"delete",employeeId:button.dataset.id}});if(response.error||response.data?.error)throw new Error(response.error?.message||response.data?.error);if(state.activeId===button.dataset.id)state.activeId=state.profile.id;await loadPeople();await reload();notify("Mitarbeiter gelöscht.")}}catch(error){notify(error.message||"Aktion fehlgeschlagen.",true)}})
db.auth.onAuthStateChange((_event,session)=>{if(session?.access_token!==state.session?.access_token){state.session=session;boot()}})
boot()

function assignmentsView(){const employees=state.people.filter(row=>row.role==="employee"),days=weekDates();if(!chief())return "";return "<main><section class='hero'><p class='eyebrow'>AUFTRÄGE MITARBEITER</p><h1>Arbeitsscheine im Team</h1><p>Wähle einen Mitarbeiter und einen Tag, um alle erstellten Arbeitsscheine vollständig anzusehen.</p></section><section class='assignment-days'>"+days.map(value=>"<article class='card assignment-day'><div class='cardhead'><div><small>"+dateText(value)+"</small><h2>"+new Intl.DateTimeFormat("de-DE",{weekday:"long"}).format(day(value))+"</h2></div></div><div class='assignment-people'>"+(employees.length?employees.map(employee=>{const count=state.data.teamOrders.filter(order=>order.employee_id===employee.id&&same(order.work_date,value)).length;return "<button data-action='team-orders' data-employee='"+employee.id+"' data-date='"+value+"'><b>"+escape(employee.username)+"</b><span>"+count+" Arbeitsschein"+(count===1?"":"e")+"</span></button>"}).join(""):"<p>Keine Mitarbeiter angelegt.</p>")+"</div></article>").join("")+"</section></main>"}
function assignmentDetailView(){const orders=state.data.orders.filter(order=>same(order.work_date,state.date));return "<main><section class='hero'><p class='eyebrow'>AUFTRÄGE MITARBEITER</p><h1>"+escape(person().username)+" · "+dateText(state.date)+"</h1><p>Vollständige Arbeitsscheine dieses Tages.</p></section><p><button data-action='team-orders-back'>← Zur Mitarbeiterübersicht</button></p><section class='cards'>"+(orders.length?orders.map(orderCard).join(""):"<p class='empty'>Für diesen Tag wurden keine Arbeitsscheine erstellt.</p>")+"</section></main>"}

async function saveCustomerDetails(form){const row=state.data.customers.find(item=>item.id===form.dataset.id),name=form.name.value.trim();if(!row)throw new Error("Kunde nicht gefunden.");if(!name)throw new Error("Bitte einen Kundennamen eingeben.");if(state.data.customers.some(item=>item.id!==row.id&&item.name.localeCompare(name,"de",{sensitivity:"accent"})===0))throw new Error("Dieser Kundenname existiert bereits.");const before={name:row.name,custom_fields:{...(row.custom_fields||{})}},fields={...before.custom_fields,address:form.address.value.trim(),city:form.city.value.trim(),postal_code:form.postal_code.value.trim(),email:form.email.value.trim(),phone_private:form.phone_private.value.trim(),phone_mobile:form.phone_mobile.value.trim()};await mutate(()=>{row.name=name;row.custom_fields=fields;return()=>Object.assign(row,before)},()=>api(db.from("customers").update({name,custom_fields:fields}).eq("id",row.id).select().single()).then(saved=>Object.assign(row,saved)),"Kundendaten gespeichert.")}
async function moveMessage(id,deleted){const row=state.data.messages.find(item=>item.id===id);if(!row)return;const before=row.deleted_at,next=deleted?new Date().toISOString():null;await mutate(()=>{row.deleted_at=next;return()=>row.deleted_at=before},()=>api(db.from("mailbox_messages").update({deleted_at:next}).eq("id",id).select().single()).then(saved=>Object.assign(row,saved)),deleted?"Nachricht in den Papierkorb verschoben.":"Nachricht wiederhergestellt.")}
root.addEventListener("submit",async event=>{const form=event.target.closest("form");if(!form||!["customer-details","document"].includes(form.dataset.form))return;event.preventDefault();try{if(form.dataset.form==="customer-details")await saveCustomerDetails(form);else await uploadDocuments(form)}catch(error){notify(error.message||"Aktion fehlgeschlagen.",true)}})
root.addEventListener("click",async event=>{const button=event.target.closest("button");if(!button)return;try{if(button.dataset.action==="mail-delete")await moveMessage(button.dataset.id,true);else if(button.dataset.action==="mail-restore")await moveMessage(button.dataset.id,false);else if(button.dataset.action==="document-open")await openDocument(button.dataset.id);else if(button.dataset.action==="document-delete")await deleteDocument(button.dataset.id);else if(button.dataset.action==="week-day"){state.date=button.dataset.date;state.month=day(state.date).getMonth();state.year=day(state.date).getFullYear();render()}else if(button.dataset.action==="team-orders"){if(!chief())throw new Error("Nur der Chef kann Mitarbeiteraufträge ansehen.");state.activeId=button.dataset.employee;state.date=button.dataset.date;state.month=day(state.date).getMonth();state.year=day(state.date).getFullYear();state.view="assignment-detail";await reload()}else if(button.dataset.action==="team-orders-back"){state.view="assignments";render()}}catch(error){notify(error.message||"Aktion fehlgeschlagen.",true)}})
root.addEventListener("change",event=>{const input=event.target;if(input?.name!=="workDate"||input.closest("form")?.dataset.form!=="order")return;const button=input.closest("form").querySelector("button.primary"),blocked=dayStatus(input.value).sick;if(button){button.disabled=blocked;button.title=blocked?"An Krankheitstagen sind keine Arbeitsscheine möglich.":""}})

// Ergänzende Chefaktionen bleiben bewusst getrennt von den Kernabläufen.
root.addEventListener("submit",async event=>{const form=event.target.closest("form");if(!form||!chief())return;try{if(form.dataset.form==="column"){const row={id:guid(),employee_id:state.activeId,name:form.name.value.trim(),position:state.data.columns.length};if(!row.name)throw new Error("Bitte Feldbezeichnung eingeben.");await mutate(()=>add(state.data.columns,row),()=>api(db.from("custom_columns").insert(row).select().single()).then(saved=>Object.assign(row,saved)),"Eingabefeld hinzugefügt.")}else if(form.dataset.form==="employee-update-full"){const response=await db.functions.invoke("manage-employees",{body:{action:"update",employeeId:form.dataset.id,username:form.username.value,password:form.password.value,vacationAllowance:form.allowance.value,menuPermissions:{planner:form.time.checked,customers:form.customers.checked,orders:form.orders.checked,calendar:form.calendar.checked}}});if(response.error||response.data?.error)throw new Error(response.error?.message||response.data?.error);await loadPeople();render();notify("Mitarbeiter gespeichert.")}}catch(error){notify(error.message||"Aktion fehlgeschlagen.",true)}})
root.addEventListener("click",async event=>{const button=event.target.closest("button");if(!button||!chief())return;try{if(button.dataset.action==="column-delete"&&window.confirm("Eingabefeld entfernen? Bestehende Werte bleiben erhalten."))await mutate(()=>remove(state.data.columns,button.dataset.id),()=>api(db.from("custom_columns").delete().eq("id",button.dataset.id).select("id")),"Eingabefeld entfernt.");else if(button.dataset.action==="material-edit"){const row=state.data.materials.find(item=>item.id===button.dataset.id),value=window.prompt("Neuer Preis für "+row?.name+" (€):",String(row?.unit_price??""));if(value===null||!row)return;const before={...row};row.unit_price=Math.max(0,number(value));await mutate(()=>()=>Object.assign(row,before),()=>api(db.from("materials").update({unit_price:row.unit_price}).eq("id",row.id).select().single()).then(saved=>Object.assign(row,saved)),"Materialpreis gespeichert.")}}catch(error){notify(error.message||"Aktion fehlgeschlagen.",true)}})
